package com.rescuefarm.ui.engagement;public final class EngagementState{public enum Status{IDLE,LOADING,SUCCESS,ERROR}private final Status status;private final String message;public EngagementState(Status s,String m){status=s;message=m==null?"":m;}public Status getStatus(){return status;}public String getMessage(){return message;}public static EngagementState idle(){return new EngagementState(Status.IDLE,"");}public static EngagementState loading(){return new EngagementState(Status.LOADING,"Đang xử lý…");}public static EngagementState success(String m){return new EngagementState(Status.SUCCESS,m);}public static EngagementState error(String m){return new EngagementState(Status.ERROR,m);}}
